		}
		commits = append(commits, commit)
	}
	return commits, nil
}

func collectFirstParentCommitsSince(
	ctx context.Context,
	repo *git.Repository,
	repoPath string,
	tip, boundary plumbing.Hash,
) ([]*object.Commit, error) {
	cmd := exec.CommandContext(
		ctx, "git", "rev-list", "--first-parent", "--reverse", boundary.String()+".."+tip.String(),
	)
	cmd.Dir = repoPath
	output, err := cmd.Output()
