// fetchAndRebaseRefCommon fetches a remote ref and rebases local commits on top
// of the remote tip. Since checkpoint shards use unique paths, rebases always
// apply cleanly.
// The target can be a remote name or a URL.
func fetchAndRebaseRefCommon(ctx context.Context, target string, ref plumbing.ReferenceName) error {
	return fetchAndRebaseRefWithMetadataThreshold(ctx, target, ref, OversizedCheckpointMetadataThreshold)
}

func fetchAndRebaseRefWithMetadataThreshold(ctx context.Context, target string, ref plumbing.ReferenceName, metadataThreshold int64) error {
	// No timeout: runs under doPushRef's shared budget.
	fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
	if err != nil {
		return fmt.Errorf("resolve fetch target: %w", err)
	}

	// Determine fetch refspec. When the resolved fetch target is a URL or the
	// ref isn't a branch, fetch into a temp ref (no remote-tracking shadow);
	// otherwise use the standard refs/remotes/<remote>/<branch> destination.
	var fetchedRefName plumbing.ReferenceName
	var refSpec string
	usedTempRef := remote.IsURL(fetchTarget) || !ref.IsBranch()
	if usedTempRef {
		fetchedRefName, err = newFetchTmpRef("push-recovery")
		if err != nil {
			return err
		}
		refSpec = fmt.Sprintf("+%s:%s", ref.String(), fetchedRefName)
	} else {
		refSpec = fmt.Sprintf("+%s:refs/remotes/%s/%s", ref.String(), target, ref.Short())
		fetchedRefName = plumbing.NewRemoteReferenceName(target, ref.Short())
	}

	// Use git CLI for fetch (go-git's fetch can be tricky with auth).
	// Do NOT --unshallow here: on a shallow repo with deep history (e.g. a
	// shared monorepo), --unshallow downloads the whole repository because
	// git treats shallow as a global property of the clone, not per-ref.
	// The downstream reconcile/rebase paths walk only commits visible past
	// .git/shallow (collectCommitChain / collectCommitsSince), so the
	// missing pre-shallow history isn't needed to produce a correct rebase.
	// Span the fetch separately so a slow sync can be attributed to the network
	// fetch versus the local reconcile/rebase that follows it.
	_, fetchSpan := perf.Start(ctx, "git_fetch")
	fetchOutput, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
		Remote:   fetchTarget,
		RefSpecs: []string{refSpec},
		NoTags:   true,
	})
	fetchSpan.RecordError(fetchErr)
	fetchSpan.End()
	if fetchErr != nil {
		return fmt.Errorf("fetch failed: %s", fetchOutput)
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}
	defer repo.Close()
	if usedTempRef {
		defer func() { _ = repo.Storer.RemoveReference(fetchedRefName) }() //nolint:errcheck // cleanup is best-effort
	}

	// Reconcile disconnected metadata branches before rebasing.
	// The fetch above updated the remote-tracking ref, so reconciliation
	// can compare fresh local vs remote. If disconnected (empty-orphan bug),
	// this cherry-picks local commits onto remote tip, updating the local ref.
	// If reconciliation fails, abort — proceeding to rebase on disconnected
	// refs would silently combine unrelated histories.
	if reconcileErr := ReconcileDisconnectedMetadataRef(ctx, repo, ref, fetchedRefName, os.Stderr); reconcileErr != nil {
		return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
	}

	// Get local ref (re-read after potential reconciliation update)
	localRef, err := repo.Reference(ref, true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}

	// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
	remoteRef, err := repo.Reference(fetchedRefName, true)
	if err != nil {
		return fmt.Errorf("failed to get remote ref: %w", err)
	}

	advance := func(hash plumbing.Hash) error {
		return setRefHash(repo, ref, hash)
	}

	// If local is already at or behind remote, fast-forward
	if localRef.Hash().Equal(remoteRef.Hash()) {
		return advance(remoteRef.Hash())
	}
	if ref == plumbing.NewBranchReferenceName(paths.MetadataBranchName) {
		_, handled, reconcileErr := reconcileOversizedV1ForPush(
			ctx, repo, localRef.Hash(), remoteRef.Hash(), metadataThreshold,
		)
		if reconcileErr != nil {
			return fmt.Errorf("reconcile oversized checkpoint metadata: %w", reconcileErr)
		}
		if handled {
			return nil
		}
	}

	// Find merge base
	repoPath, err := getRepoPath(repo)
	if err != nil {
		return fmt.Errorf("failed to get repo path: %w", err)
	}
	mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
	if err != nil {
		return fmt.Errorf("failed to find merge base: %w", err)
	}

	// If local is ancestor of remote (merge base == local), fast-forward to remote
	if mergeBase.Equal(localRef.Hash()) {
		if err := advance(remoteRef.Hash()); err != nil {
			return fmt.Errorf("failed to fast-forward ref: %w", err)
		}
		return nil
	}

	// Collect commits reachable from local but not from remote and cherry-pick
	// them onto the remote tip. This preserves local-only commits even when the
	// local metadata branch already contains old merge commits, while avoiding
	// replaying shared ancestors older than the true merge-base.
	localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to collect local commits: %w", err)
	}

	if len(localCommits) == 0 {
		// No local-only commits — just point to remote
		return advance(remoteRef.Hash())
	}

	shallow, err := loadShallowHashes(ctx, repoPath)
	if err != nil {
		return fmt.Errorf("failed to load shallow boundaries: %w", err)
	}

	newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits, shallow)
	if err != nil {
		return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
	}

	return advance(newTip)
}

// getMergeBase returns the merge base hash of two commits, or an error if they
// have no common ancestor.
func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
	cmd.Dir = repoPath
	output, err := cmd.Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
			return plumbing.ZeroHash, errNoMergeBase
		}
		return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
	}

	mergeBase := strings.TrimSpace(string(output))
	if mergeBase == "" {
		return plumbing.ZeroHash, errNoMergeBase
	}
	return plumbing.NewHash(mergeBase), nil
}

// collectCommitsSince returns non-merge commits reachable from tip but not from
// exclude, ordered oldest-first in topological order.
func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	// cherryPickOnto computes each commit's delta against its first parent, so
	// replaying merge commits would incorrectly re-apply changes that arrived via
	// non-first-parent history. Limit the replay set to non-merge commits.
	cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
	cmd.Dir = repoPath
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("git rev-list failed: %w", err)
	}

	lines := strings.Fields(string(output))
	if len(lines) > MaxCommitTraversalDepth {
		return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
	}

	commits := make([]*object.Commit, 0, len(lines))
	for _, line := range lines {
		hash := plumbing.NewHash(line)
		commit, commitErr := repo.CommitObject(hash)
		if commitErr != nil {
			return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
		}
		if len(commit.ParentHashes) > 1 {
			continue
		}
		commits = append(commits, commit)
	}

	return commits, nil
}

// startProgressDots prints dots to w every second until the returned stop function
// is called. The stop function prints the given suffix and a newline.
func startProgressDots(w io.Writer) func(suffix string) {
	done := make(chan struct{})
	stopped := make(chan struct{})
	go func() {
		defer close(stopped)
		ticker := time.NewTicker(time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-done:
				return
			case <-ticker.C:
				fmt.Fprint(w, ".")
			}
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		set[plumbing.NewHash(line)] = true
	}
	return set, nil
}

// cherryPickOnto applies each commit's delta onto base, building a linear chain.
// For each commit, it computes the full diff from its parent (additions, modifications,
// and deletions), then applies that delta onto the current tip's tree.
//
// Commits listed in shallow are treated as roots: their delta is computed against
// an empty tree rather than against their (past-the-boundary) parent. Without this,
// a shallow-boundary commit would be diffed against a stale parent tree whose
// objects live in the local pack but no longer represent the actual checkpoint
// history — producing nonsense changes when replayed onto the remote tip.
func cherryPickOnto(ctx context.Context, repo *git.Repository, base plumbing.Hash, commits []*object.Commit, shallow map[plumbing.Hash]bool) (plumbing.Hash, error) {
	currentTip := base

	for _, commit := range commits {
		changes, err := treeChangesForCherryPick(ctx, repo, commit, shallow)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		if len(changes) == 0 {
			continue // Skip no-op commits
		}

		tipCommit, err := repo.CommitObject(currentTip)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
		}

		mergedTreeHash, err := checkpoint.ApplyTreeChanges(ctx, repo, tipCommit.TreeHash, changes)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to apply cherry-pick changes: %w", err)
		}
		if mergedTreeHash.Equal(tipCommit.TreeHash) {
			continue
		}

		// Create new commit on top of current tip, preserving original message/author
		newHash, err := createCherryPickCommit(ctx, repo, mergedTreeHash, currentTip, commit)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
		}

		currentTip = newHash
	}

	return currentTip, nil
}

func treeChangesForCherryPick(ctx context.Context, repo *git.Repository, commit *object.Commit, shallow map[plumbing.Hash]bool) ([]checkpoint.TreeChange, error) {
	commitTree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
	}

	var parentTree *object.Tree
	// Shallow-boundary commits are treated as roots — see cherryPickOnto for why.
	if len(commit.ParentHashes) > 0 && !shallow[commit.Hash] {
		parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
		if pErr != nil {
			return nil, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
		}
		parentTree, err = parentCommit.Tree()
		if err != nil {
			return nil, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], err)
		}
	}

	changes, err := object.DiffTreeContext(ctx, parentTree, commitTree)
	if err != nil {
		return nil, fmt.Errorf("failed to diff commit %s against parent: %w", commit.Hash, err)
	}

	treeChanges := make([]checkpoint.TreeChange, 0, len(changes))
	for _, change := range changes {
		treeChange, changeErr := changeToTreeChange(change)
		if changeErr != nil {
			return nil, fmt.Errorf("failed to convert change in commit %s: %w", commit.Hash, changeErr)
		}
		treeChanges = append(treeChanges, treeChange)
	}
	return treeChanges, nil
}

func changeToTreeChange(change *object.Change) (checkpoint.TreeChange, error) {
	action, err := change.Action()
	if err != nil {
		return checkpoint.TreeChange{}, fmt.Errorf("change action: %w", err)
	}

	switch action {
	case merkletrie.Insert, merkletrie.Modify:
		entry := change.To.TreeEntry
		return checkpoint.TreeChange{
			Path: change.To.Name,
			Entry: &object.TreeEntry{
				Name: entry.Name,
				Mode: entry.Mode,
				Hash: entry.Hash,
			},
		}, nil
	case merkletrie.Delete:
		return checkpoint.TreeChange{Path: change.From.Name}, nil
	default:
		return checkpoint.TreeChange{}, fmt.Errorf("unsupported action %s", action)
	}
}

// createCherryPickCommit creates a new commit on top of parent, preserving the
// original commit's message and author.
func createCherryPickCommit(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
	committerName, committerEmail := GetGitAuthorFromRepo(repo)
	now := time.Now()

	commit := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: []plumbing.Hash{parent},
		Author:       original.Author,
		Committer: object.Signature{
			Name:  committerName,
			Email: committerEmail,
			When:  now,
		},
		Message: original.Message,
	}

	checkpoint.SignCommitBestEffort(ctx, commit)

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

// getRepoPath returns the filesystem path for the repository's worktree.
func getRepoPath(repo *git.Repository) (string, error) {
	wt, err := repo.Worktree()
	if err != nil {
		return "", fmt.Errorf("failed to get worktree: %w", err)
	}
	return wt.Filesystem().Root(), nil
}
}

// rawByteCapMultiplier ties the raw-byte RAM ceiling to the leaf-byte
// inference cap. 100× means: leaf cap 2 MiB → raw ceiling 200 MiB.
// Picked to comfortably exceed any realistic JSON-scaffolding ratio
// (a 10 MiB JSONL with 300 KB of leaves still fits) while preventing
// pathological RAM blowups (a 5 GiB pasted dump aborts before loading).
const rawByteCapMultiplier = 100

// RewriteUnpushedV1WithOPF re-redacts unpushed entire/checkpoints/v1
// commits with OPF, builds new commits carrying Entire-OPF-Applied:
// true, and CAS-updates the local ref. Idempotent: already-applied
// commits are re-parented without re-running OPF.
//
// Caller checks redact.OPFEnabled() and skips this when OPF is off.
// Returns one of {V1DivergedError, BootstrapTooLargeError,
// V1RefMovedError, OPFRuntimeFailedError, OPFNoCategoriesError,
// OPFBatchTooLargeError, OPFRawBytesTooLargeError} for
// privacy-critical failures — the pre-push hook propagates these so
// git push aborts.
func RewriteUnpushedV1WithOPF(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
	return rewriteUnpushedV1WithOPF(ctx, repo, target, OversizedCheckpointMetadataThreshold)
}

func rewriteUnpushedV1WithOPF(ctx context.Context, repo *git.Repository, target string, metadataThreshold int64) (plumbing.Hash, error) {
	localTip, err := readV1Tip(repo, plumbing.NewBranchReferenceName(paths.MetadataBranchName))
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read local v1: %w", err)
	}
	if localTip.IsZero() {
		return plumbing.ZeroHash, nil // no checkpoints yet
	}
	remoteTip, err := resolveRemoteV1Tip(ctx, repo, target)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read remote v1: %w", err)
	}

	reconciledTip, handled, reconcileErr := reconcileOversizedV1ForPush(
		ctx, repo, localTip, remoteTip, metadataThreshold,
	)
	if reconcileErr != nil {
		return plumbing.ZeroHash, fmt.Errorf("reconcile oversized checkpoint metadata: %w", reconcileErr)
	}
	if handled {
		localTip = reconciledTip
	}

	if !remoteTip.IsZero() {
		mergeBase, mbErr := computeMergeBase(repo, localTip, remoteTip)
		if mbErr != nil {
			return plumbing.ZeroHash, fmt.Errorf("compute merge-base: %w", mbErr)
		}
		if mergeBase != remoteTip {
			return plumbing.ZeroHash, &V1DivergedError{Local: localTip, Remote: remoteTip, MergeBase: mergeBase}
		}
	}

	unpushed, err := listUnpushedV1Commits(repo, localTip, remoteTip)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("list unpushed v1 commits: %w", err)
	}
	if len(unpushed) == 0 {
		return localTip, nil
	}
	if remoteTip.IsZero() {
		if limit := resolveBootstrapLimit(); len(unpushed) > limit {
			return plumbing.ZeroHash, &BootstrapTooLargeError{Count: len(unpushed), Limit: limit}
		}
	}

	// Fail-closed defense: enabled-with-no-categories means the model
	// scan can't run at all. The decision resolution in prePush already
	// rejects this state before any prompt; this second gate covers
	// direct callers and sits before the breaker check so the user gets
	// the config-specific remediation rather than OPFRuntimeFailedError's
	// "verify your OPF install".
	if redact.OPFMisconfiguredNoCategories() {
		return plumbing.ZeroHash, &OPFNoCategoriesError{}
	}

	// Fail-closed defense: if OPF is already broken at the start of
	// this push (an earlier process step tripped the breaker), abort
	// before tagging any commits as OPF-applied. Without this, the
	// per-blob fallback inside the no-OPF cases of BatchBytesWithPrivacyFilter
	// could let regex-only content slip out with the trailer attached.
	if redact.OPFBreakerTripped() {
		return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
	}

	// Pass 1: collect every redactable blob from every unpushed commit
	// that still needs OPF. Already-applied commits get re-parented
	// later without collecting (their tree stays as-is). We also track
	// each blob's source commit + tree path so we can route the redacted
	// bytes back during apply.
	type pendingCommit struct {
		commit *object.Commit
		// blobs and paths are parallel slices; len(paths)==len(blobs).
		// startIdx is this commit's offset into the global redacted slice.
		blobs    []redact.NamedBlob
		paths    []string
		startIdx int
	}
	var globalBlobs []redact.NamedBlob
	pendings := make([]pendingCommit, 0, len(unpushed))
	// Bound raw-bytes-in-memory incrementally so a pathological push
	// (e.g. 5 GiB of pasted dumps) aborts before exhausting the user's
	// shell RAM. The leaf-byte cap downstream is about inference cost;
	// this one is about memory ceiling and fires earlier. scaleBatchLimit
	// saturates at math.MaxInt so "unlimited" actually means unlimited
	// — without saturation, "unlimited" × 100 overflows int and the cap
	// trips on every push.
	rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
	var rawBytesSoFar int
	for _, c := range unpushed {
		pc := pendingCommit{commit: c}
		if !trailers.HasOPFApplied(c.Message) {
			tree, err := repo.TreeObject(c.TreeHash)
			if err != nil {
				return plumbing.ZeroHash, fmt.Errorf("load tree for %s: %w", c.Hash.String()[:7], err)
			}
			pc.startIdx = len(globalBlobs)
			// Whole-tree redaction: each v1 commit tree is cumulative, so the
			// newest commit can still carry older shards that were regex-only
			// before this rewrite. Redacting the whole tree for every unapplied
			// commit keeps the final rewritten tip from reintroducing an
			// un-OPF-redacted older shard. collect and apply walk the tree the
			// same way so the cached keys line up.
			if err := collectTreeBlobs(repo, tree, "", &pc.blobs, &pc.paths); err != nil {
				return plumbing.ZeroHash, fmt.Errorf("collect blobs %s: %w", c.Hash.String()[:7], err)
			}
			for _, b := range pc.blobs {
				rawBytesSoFar += len(b.Content)
			}
			if rawBytesSoFar > rawCap {
				return plumbing.ZeroHash, &OPFRawBytesTooLargeError{RawBytes: rawBytesSoFar, Limit: rawCap}
			}
			globalBlobs = append(globalBlobs, pc.blobs...)
		}
		pendings = append(pendings, pc)
	}

	// Pass 2: enforce the leaf-byte cap, then make exactly ONE OPF
	// shell-out for the whole push. The cap runs before the shell-out
	// so a too-large push fails fast with a clear remediation message.
	var globalRedacted [][]byte
	if len(globalBlobs) > 0 {
		leafBytes := redact.SumProseLeafBytes(globalBlobs)
		if limit := resolveBatchLimit(); leafBytes > limit {
			return plumbing.ZeroHash, &OPFBatchTooLargeError{LeafBytes: leafBytes, Limit: limit}
		}
		globalRedacted, err = redact.BatchBytesWithPrivacyFilter(ctx, globalBlobs)
		if err != nil {
			// Converge with the up-front gate: the misconfiguration
			// sentinel must surface config remediation, not "verify
			// your OPF install".
			if errors.Is(err, redact.ErrOPFNoEnabledCategories) {
				return plumbing.ZeroHash, &OPFNoCategoriesError{}
			}
			return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand(), Cause: err}
		}
	}

	// Pass 3: rebuild each commit. For OPF-applied commits, this is
	// just a re-parent (no tree changes). For unapplied commits, the
	// per-commit redaction map routes cached bytes by tree path.
	parent := remoteTip
	for _, pc := range pendings {
		var redactedByPath map[string][]byte
		if len(pc.blobs) > 0 {
			redactedByPath = make(map[string][]byte, len(pc.blobs))
			for i, path := range pc.paths {
				redactedByPath[path] = globalRedacted[pc.startIdx+i]
			}
		}
		newHash, err := rebuildCheckpointCommit(ctx, repo, pc.commit, parent, redactedByPath)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("rebuild commit %s: %w", pc.commit.Hash.String()[:7], err)
		}
		parent = newHash
	}

	if err := atomicSetV1Ref(ctx, repo, localTip, parent); err != nil {
		return plumbing.ZeroHash, err
	}
	return parent, nil
}

func readV1Tip(repo *git.Repository, refName plumbing.ReferenceName) (plumbing.Hash, error) {
	ref, err := repo.Reference(refName, true)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return plumbing.ZeroHash, nil
		}
		return plumbing.ZeroHash, fmt.Errorf("resolve ref %s: %w", refName, err)
	}
	return ref.Hash(), nil
}

