537	// getRepoPath returns the filesystem path for the repository's worktree.
538	func getRepoPath(repo *git.Repository) (string, error) {
539		wt, err := repo.Worktree()
540		if err != nil {
100			if pendingCaptureCheckpointSyncRemote(ctx, ps.remote) {
101				pendingCapture = ps.remote
102			}
103			if !checkpointSyncAllowedForRemote(ctx, ps.remote, pendingCapture) {
104				hintGatedCheckpointSync(ctx, ps.remote)
105				return nil
106			}
107		}
108	
109		// git-refs primary: push the per-checkpoint refs recorded in the push queue
110		// instead of the single v1 branch. Those refs live under refs/entire/, not
111		// refs/heads/, so a forge can never pick them as a repository's default
112		// branch — the empty-remote guard below is unnecessary for this backend.
113		// (A configured git-branch mirror's v1 ref is not pushed here yet — mirror
114		// push for downgrade safety is a later step.)
115		if ps.primaryIsRefs {
116			return s.prePushCheckpointRefs(ctx, ps, pendingCapture)
117		}
118	
119		// git-branch primary: entire/checkpoints/v1 is a real refs/heads branch, so
120		// on an otherwise-empty remote a forge like GitHub would select it as the
121		// default. Defer publication until the user's own branch exists there.
122		deferAutomaticCheckpointPush := protectFirstUserBranch && deferCheckpointPushOnEmptyRemote(ctx, ps)
123	
124		refs := checkpoint.ResolveRefs(ctx)
125		repo, repoErr := OpenRepository(ctx)
126		if repoErr != nil {
127			logging.Warn(ctx, "checkpoint policy pre-push: failed to open repository; allowing checkpoint push",
128				slog.String("error", repoErr.Error()),
129			)
130		} else {
131			defer repo.Close()
132			syncCheckpointPolicyForPrePush(ctx, repo, ps)
133			if !checkpointPolicyAllowsGitHook(ctx, repo) {
134				// Policy failures should skip checkpoint pushes, not abort the user's push.
135				return nil
136			}
137			if err := prepareOversizedV1ForPush(
138				ctx, repo, ps.pushTarget(), OversizedCheckpointMetadataThreshold,
139			); err != nil {
140				logging.Warn(ctx, "checkpoint metadata cleanup failed; aborting push",
141					slog.String("error", err.Error()),
142				)
143				fmt.Fprintf(os.Stderr, "[entire] Checkpoint metadata cleanup failed: %v\n", err)
144				return err
145			}
146		}
147	
148		// OPF pre-push rewrite: if OPF is configured, resolve the user's
149		// decision (env > settings > prompt > non-TTY auto-run), then
150		// re-redact unpushed v1 commits with OPF (producing the OPF-applied,
151		// 9-layer pipeline) before pushing. Skipped entirely when OPF is off,
152		// so the common-case fast path is unchanged.
153		if redact.OPFEnabled() {
154			decision, decisionErr := opfPrePushDecision(ctx)
155			if decisionErr != nil {
156				logging.Warn(ctx, "OPF pre-push decision failed; aborting push",
157					slog.String("error", decisionErr.Error()),
158				)
159				return decisionErr
160			}
161			switch decision {
162			case OPFAbort:
163				return ErrOPFAbortedByUser
164			case OPFSkip:
165				// User opted out for this push (or settings/env say
166				// "never"). Push regex-only (8-layer) content as-is.
167				logging.Info(ctx, "OPF skipped for this push (user choice or settings)")
168			case OPFRun:
169				_, opfSpan := perf.Start(ctx, "opf_pre_push_rewrite")
170				if repoErr != nil {
171					opfSpan.RecordError(repoErr)
172					opfSpan.End()
173					logging.Warn(ctx, "OPF pre-push: failed to open repo; aborting push",
174						slog.String("error", repoErr.Error()),
175					)
176					return repoErr
177				}
178				if _, rewriteErr := RewriteUnpushedV1WithOPF(ctx, repo, ps.pushTarget()); rewriteErr != nil {
179					opfSpan.RecordError(rewriteErr)
180					opfSpan.End()
181					logging.Warn(ctx, "OPF pre-push rewrite failed; aborting push",
182						slog.String("error", rewriteErr.Error()),
183					)
184					return rewriteErr
185				}
186				opfSpan.End()
187			}
188		}
189	
190		if deferAutomaticCheckpointPush {
191			// Do this only after OPF has had a chance to rewrite v1: the outer
192			// user push may explicitly include the metadata branch.
193			logging.Info(ctx, "automatic checkpoint push deferred until the remote has a branch",
194				slog.String("remote", ps.remote),
195			)
196			return nil
197		}
198	
199		// Thread the span's context into the push so the network push and any
200		// fetch+rebase recovery nest beneath it as child steps in the perf trace.
201		pushCtx, pushCheckpointsSpan := perf.Start(ctx, "push_checkpoint_refs")
202		// Capture needs checkpoint data CONFIRMED on this remote, so count what
203		// landed rather than trusting the absence of an error: every ref that was due
204		// has to deliver, and at least one has to actually do so. Delivery must come
205		// from pushRefIfNeeded's delivered return and NOT from err, which is
206		// fail-soft and nil even when the remote refused the ref.
207		deliveredCount, anyFailed := 0, false
208		for _, ref := range refs.Push {
209			delivered, err := pushRefIfNeeded(pushCtx, ps.pushTarget(), ref)
210			if err != nil {
211				pushCheckpointsSpan.RecordError(err)
212				pushCheckpointsSpan.End()
213				return err
214			}
215			if delivered {
216				deliveredCount++
217			} else {
218				anyFailed = true
219			}
220		}
221		pushCheckpointsSpan.End()
222	
223		// Delivered: the election may now follow the push that carried it. A push that
224		// carried nothing — an empty ref set, or a v1 ref that does not exist locally
225		// yet — leaves the election alone. It is safe either way (nothing is stranded
226		// when there was nothing to strand), but capturing would announce a move that
227		// moved no data, which is the class of claim this whole path exists to stop
228		// making. The next push that carries a checkpoint captures instead.
229		if pendingCapture != "" && deliveredCount > 0 && !anyFailed {
230			commitCapturedSyncRemote(ctx, pendingCapture)
231		}
232	
233		cleanupPushedShadowBranches(ctx)
234		return nil
235	}
