   585		ctx       context.Context //nolint:containedctx // scoped to one rewrite; threaded into commit signing
   586		repo      *git.Repository
   587		threshold int64
   588	
   589		blobs   map[plumbing.Hash]plumbing.Hash
   590		trees   map[plumbing.Hash]plumbing.Hash
   591		commits map[plumbing.Hash]plumbing.Hash
   592		shallow map[plumbing.Hash]bool
   593	
   594		commitsRewritten int
   595		blobsShrunk      int
   596		stillOversized   []OversizedMetadataBlob
   597	}
   598	
   599	func newMetadataRewriter(ctx context.Context, repo *git.Repository, threshold int64) *metadataRewriter {
   600		return &metadataRewriter{
   601			ctx:       ctx,
   602			repo:      repo,
   603			threshold: threshold,
   604			blobs:     make(map[plumbing.Hash]plumbing.Hash),
   605			trees:     make(map[plumbing.Hash]plumbing.Hash),
   606			commits:   make(map[plumbing.Hash]plumbing.Hash),
   607		}
   608	}
