   610	// rewriteHistory returns the rewritten equivalent of tip. Parents are processed
   611	// before children with an explicit stack, so a branch with thousands of
   612	// checkpoints does not recurse thousands deep.
   613	func (r *metadataRewriter) rewriteHistory(tip plumbing.Hash) (plumbing.Hash, error) {
   614		if tip.IsZero() {
   615			return tip, nil
   616		}
   617		type frame struct {
   618			hash     plumbing.Hash
   619			expanded bool
   620		}
   621		stack := []frame{{hash: tip}}
   622		for len(stack) > 0 {
   623			if err := r.ctx.Err(); err != nil {
   624				return plumbing.ZeroHash, err //nolint:wrapcheck // context cancellation propagates as-is
   625			}
   626			top := len(stack) - 1
   627			f := stack[top]
   628			if _, done := r.commits[f.hash]; done {
   629				stack = stack[:top]
   630				continue
   631			}
   632			c, err := r.repo.CommitObject(f.hash)
   633			if err != nil {
   634				return plumbing.ZeroHash, fmt.Errorf("load commit %s: %w", f.hash, err)
   635			}
   636			if r.shallow[f.hash] {
   637				oversizedPath, err := oversizedMetadataPathInTree(r.repo, c.TreeHash, r.threshold)
   638				if err != nil {
   639					return plumbing.ZeroHash, fmt.Errorf("inspect shallow boundary %s: %w", f.hash, err)
   640				}
   641				if oversizedPath != "" {
   642					return plumbing.ZeroHash, &ShallowMetadataRepairError{Boundary: f.hash, Path: oversizedPath}
   643				}
   644				r.commits[f.hash] = f.hash
   645				stack = stack[:top]
   646				continue
   647			}
   648			if !f.expanded {
   649				stack[top].expanded = true
   650				for _, p := range c.ParentHashes {
   651					if _, done := r.commits[p]; !done {
   652						stack = append(stack, frame{hash: p})
   653					}
   654				}
   655				continue
   656			}
   657			newHash, err := r.rewriteCommit(c)
   658			if err != nil {
   659				return plumbing.ZeroHash, err
   660			}
   661			r.commits[f.hash] = newHash
   662			stack = stack[:top]
   663		}
   664		return r.commits[tip], nil
   665	}
