   667	func (r *metadataRewriter) rewriteCommit(c *object.Commit) (plumbing.Hash, error) {
   668		newTree, err := r.rewriteTree(c.TreeHash, "")
   669		if err != nil {
   670			return plumbing.ZeroHash, err
   671		}
   672		parents := make([]plumbing.Hash, 0, len(c.ParentHashes))
   673		changed := !newTree.Equal(c.TreeHash)
   674		for _, p := range c.ParentHashes {
   675			np, ok := r.commits[p]
   676			if !ok {
   677				return plumbing.ZeroHash, fmt.Errorf("parent %s of %s was not rewritten first", p, c.Hash)
   678			}
   679			if !np.Equal(p) {
   680				changed = true
   681			}
   682			parents = append(parents, np)
   683		}
   684		if !changed {
   685			return c.Hash, nil
   686		}
   687		rewritten := &object.Commit{
   688			Author:       c.Author,
   689			Committer:    c.Committer,
   690			Message:      c.Message,
   691			TreeHash:     newTree,
   692			ParentHashes: parents,
   693			Encoding:     c.Encoding,
   694			ExtraHeaders: c.ExtraHeaders,
   695		}
   696		// Re-sign when signing is configured: the original signature covered the
   697		// original tree, so it cannot be carried over. Signing makes the rewritten
   698		// hash non-deterministic across runs, which is why reconciliation below
   699		// compares trees (contentReachable) rather than hashes.
   700		checkpoint.SignCommitBestEffort(r.ctx, rewritten)
   701		obj := r.repo.Storer.NewEncodedObject()
   702		if err := rewritten.Encode(obj); err != nil {
   703			return plumbing.ZeroHash, fmt.Errorf("encode rewritten commit %s: %w", c.Hash, err)
   704		}
   705		hash, err := r.repo.Storer.SetEncodedObject(obj)
   706		if err != nil {
   707			return plumbing.ZeroHash, fmt.Errorf("store rewritten commit %s: %w", c.Hash, err)
   708		}
   709		r.commitsRewritten++
   710		return hash, nil
   711	}
