483	func fetchAndRebaseRefWithMetadataThreshold(ctx context.Context, target string, ref plumbing.ReferenceName, metadataThreshold int64) error {
484		// No timeout: runs under doPushRef's shared budget.
485		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
486		if err != nil {
487			return fmt.Errorf("resolve fetch target: %w", err)
488		}
489	
490		// Determine fetch refspec. When the resolved fetch target is a URL or the
491		// ref isn't a branch, fetch into a temp ref (no remote-tracking shadow);
492		// otherwise use the standard refs/remotes/<remote>/<branch> destination.
493		var fetchedRefName plumbing.ReferenceName
494		var refSpec string
495		usedTempRef := remote.IsURL(fetchTarget) || !ref.IsBranch()
496		if usedTempRef {
497			fetchedRefName, err = newFetchTmpRef("push-recovery")
498			if err != nil {
499				return err
500			}
501			refSpec = fmt.Sprintf("+%s:%s", ref.String(), fetchedRefName)
502		} else {
503			refSpec = fmt.Sprintf("+%s:refs/remotes/%s/%s", ref.String(), target, ref.Short())
504			fetchedRefName = plumbing.NewRemoteReferenceName(target, ref.Short())
505		}
506		repo, err := OpenRepository(ctx)
507		if err != nil {
508			return fmt.Errorf("failed to open git repository: %w", err)
509		}
510		defer repo.Close()
511		if usedTempRef {
512			defer func() { _ = repo.Storer.RemoveReference(fetchedRefName) }() //nolint:errcheck // cleanup is best-effort
513		}
514	
515		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
516		// Do NOT --unshallow here: on a shallow repo with deep history (e.g. a
517		// shared monorepo), --unshallow downloads the whole repository because
518		// git treats shallow as a global property of the clone, not per-ref.
519		// The downstream reconcile/rebase paths walk only commits visible past
520		// .git/shallow (collectCommitChain / collectCommitsSince), so the
521		// missing pre-shallow history isn't needed to produce a correct rebase.
522		// Span the fetch separately so a slow sync can be attributed to the network
523		// fetch versus the local reconcile/rebase that follows it.
524		_, fetchSpan := perf.Start(ctx, "git_fetch")
525		fetchOutput, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
526			Remote:   fetchTarget,
527			RefSpecs: []string{refSpec},
528			NoTags:   true,
529		})
530		fetchSpan.RecordError(fetchErr)
531		fetchSpan.End()
532		if fetchErr != nil {
533			return fmt.Errorf("fetch failed: %s", fetchOutput)
534		}
535	
536		// Reconcile disconnected metadata branches before rebasing.
537		// The fetch above updated the remote-tracking ref, so reconciliation
538		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
539		// this cherry-picks local commits onto remote tip, updating the local ref.
540		// If reconciliation fails, abort — proceeding to rebase on disconnected
541		// refs would silently combine unrelated histories.
542		if reconcileErr := ReconcileDisconnectedMetadataRef(ctx, repo, ref, fetchedRefName, os.Stderr); reconcileErr != nil {
543			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
544		}
545	
546		// Get local ref (re-read after potential reconciliation update)
547		localRef, err := repo.Reference(ref, true)
548		if err != nil {
549			return fmt.Errorf("failed to get local ref: %w", err)
550		}
551	
552		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
553		remoteRef, err := repo.Reference(fetchedRefName, true)
554		if err != nil {
555			return fmt.Errorf("failed to get remote ref: %w", err)
556		}
557	
558		advance := func(hash plumbing.Hash) error {
559			return setRefHash(repo, ref, hash)
560		}
561	
562		// If local is already at or behind remote, fast-forward
563		if localRef.Hash().Equal(remoteRef.Hash()) {
564			return advance(remoteRef.Hash())
565		}
566		if ref == plumbing.NewBranchReferenceName(paths.MetadataBranchName) {
567			_, handled, reconcileErr := reconcileOversizedV1ForPush(
568				ctx, repo, localRef.Hash(), remoteRef.Hash(), metadataThreshold,
569			)
570			if reconcileErr != nil {
571				return fmt.Errorf("reconcile oversized checkpoint metadata: %w", reconcileErr)
572			}
573			if handled {
574				return nil
575			}
576		}
577	
578		// Find merge base
579		repoPath, err := getRepoPath(repo)
580		if err != nil {
581			return fmt.Errorf("failed to get repo path: %w", err)
582		}
583		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
584		if err != nil {
585			return fmt.Errorf("failed to find merge base: %w", err)
586		}
587	
588		// If local is ancestor of remote (merge base == local), fast-forward to remote
589		if mergeBase.Equal(localRef.Hash()) {
590			if err := advance(remoteRef.Hash()); err != nil {
591				return fmt.Errorf("failed to fast-forward ref: %w", err)
592			}
593			return nil
594		}
595	
596		// Collect commits reachable from local but not from remote and cherry-pick
597		// them onto the remote tip. This preserves local-only commits even when the
598		// local metadata branch already contains old merge commits, while avoiding
599		// replaying shared ancestors older than the true merge-base.
600		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
601		if err != nil {
602			return fmt.Errorf("failed to collect local commits: %w", err)
603		}
604	
605		if len(localCommits) == 0 {
606			// No local-only commits — just point to remote
607			return advance(remoteRef.Hash())
608		}
609	
610		shallow, err := loadShallowHashes(ctx, repoPath)
611		if err != nil {
612			return fmt.Errorf("failed to load shallow boundaries: %w", err)
613		}
614	
615		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits, shallow)
616		if err != nil {
617			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
618		}
619	
620		return advance(newTip)
621	}
