105	// reconcileOversizedV1ForPush rewrites local oversized history. An existing
106	// remote must prove where its shared checkpoint content ends before replay.
107	func reconcileOversizedV1ForPush(
108		ctx context.Context,
109		repo *git.Repository,
110		observedLocalTip, remoteTip plumbing.Hash,
111		threshold int64,
112	) (plumbing.Hash, bool, error) {
