466		if len(bases) != 1 {
467			return plumbing.ZeroHash, nil
468		}
469		return plumbing.NewHash(bases[0]), nil
470	}
480		return fetchAndRebaseRefWithMetadataThreshold(ctx, target, ref, OversizedCheckpointMetadataThreshold)
481	}
