105	// reconcileOversizedV1ForPush rewrites local oversized history. An existing
106	// remote must prove where its shared checkpoint content ends before replay.
107	func reconcileOversizedV1ForPush(
108		ctx context.Context,
109		repo *git.Repository,
110		observedLocalTip, remoteTip plumbing.Hash,
111		threshold int64,
112	) (plumbing.Hash, bool, error) {
113		if observedLocalTip.IsZero() {
114			return observedLocalTip, false, nil
115		}
116		repoPath, err := getRepoPath(repo)
117		if err != nil {
118			return plumbing.ZeroHash, false, fmt.Errorf("get repository path: %w", err)
119		}
120	
121		mergeBase := plumbing.ZeroHash
122		if !remoteTip.IsZero() {
123			mergeBase, err = computeMergeBaseWithGit(ctx, repoPath, observedLocalTip, remoteTip)
124			if err != nil {
125				return plumbing.ZeroHash, false, fmt.Errorf("compute original merge-base: %w", err)
126			}
127		}
128		hasOversizedLocalHistory, err := hasOversizedMetadataIntroducedSince(
129			ctx, repo, observedLocalTip, mergeBase, threshold,
130		)
131		if err != nil {
132			return plumbing.ZeroHash, false, err
133		}
134		if !hasOversizedLocalHistory {
135			return observedLocalTip, false, nil
136		}
137	
138		shallow, err := loadShallowHashes(ctx, repoPath)
139		if err != nil {
140			return plumbing.ZeroHash, false, fmt.Errorf("load shallow boundaries: %w", err)
141		}
142		rewriter := newMetadataRewriter(ctx, repo, threshold)
143		rewriter.shallow = shallow
144		rewrittenTip, err := rewriter.rewriteHistory(observedLocalTip)
145		if err != nil {
146			return plumbing.ZeroHash, false, fmt.Errorf("rewrite oversized local metadata: %w", err)
147		}
148		if rewriter.commitsRewritten == 0 {
149			return observedLocalTip, false, nil
150		}
151		if remoteTip.IsZero() {
152			if err := atomicSetV1Ref(ctx, repo, observedLocalTip, rewrittenTip); err != nil {
153				return plumbing.ZeroHash, false, err
154			}
155			return rewrittenTip, true, nil
156		}
157	
158		rewrittenBoundary, originalBoundary, found, err := findSharedRewrittenTree(
159			ctx, repo, repoPath, rewrittenTip, remoteTip, rewriter.commits,
160		)
161		if err != nil {
162			return plumbing.ZeroHash, false, err
163		}
164		if !found {
165			return observedLocalTip, false, nil
166		}
167	
168		if !mergeBase.IsZero() {
169			safe, err := boundaryAtOrAfterMergeBase(ctx, repoPath, mergeBase, originalBoundary)
170			if err != nil {
171				return plumbing.ZeroHash, false, err
172			}
173			if !safe {
174				return observedLocalTip, false, nil
175			}
176		}
177	
178		localOnly, err := collectFirstParentCommitsSince(ctx, repo, repoPath, rewrittenTip, rewrittenBoundary)
179		if err != nil {
180			return plumbing.ZeroHash, false, fmt.Errorf("collect local checkpoints after repaired boundary: %w", err)
181		}
182	
183		newTip := remoteTip
184		if len(localOnly) > 0 {
185			shallow, shallowErr := loadShallowHashes(ctx, repoPath)
186			if shallowErr != nil {
187				return plumbing.ZeroHash, false, fmt.Errorf("load shallow boundaries: %w", shallowErr)
188			}
189			newTip, err = cherryPickOnto(ctx, repo, remoteTip, localOnly, shallow)
190			if err != nil {
191				return plumbing.ZeroHash, false, fmt.Errorf("replay local checkpoints onto repaired remote: %w", err)
192			}
193		}
194	
195		if err := atomicSetV1Ref(ctx, repo, observedLocalTip, newTip); err != nil {
196			return plumbing.ZeroHash, false, err
197		}
198		return newTip, true, nil
199	}
