421	func collectFirstParentCommitsSince(
422		ctx context.Context,
423		repo *git.Repository,
424		repoPath string,
425		tip, boundary plumbing.Hash,
426	) ([]*object.Commit, error) {
427		cmd := exec.CommandContext(
428			ctx, "git", "rev-list", "--first-parent", "--reverse", boundary.String()+".."+tip.String(),
429		)
430		cmd.Dir = repoPath
431		output, err := cmd.Output()
432		if err != nil {
433			return nil, fmt.Errorf("git rev-list failed: %w", err)
434		}
435		hashes := strings.Fields(string(output))
436		if len(hashes) > MaxCommitTraversalDepth {
437			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
438		}
439		commits := make([]*object.Commit, 0, len(hashes))
440		for _, value := range hashes {
441			commit, err := repo.CommitObject(plumbing.NewHash(value))
442			if err != nil {
443				return nil, fmt.Errorf("load replay commit %s: %w", value, err)
444			}
445			commits = append(commits, commit)
446		}
447		return commits, nil
448	}
