625	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
626		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
627		defer cancel()
628	
629		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
630		cmd.Dir = repoPath
631		output, err := cmd.Output()
632		if err != nil {
633			var exitErr *exec.ExitError
634			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
635				return plumbing.ZeroHash, errNoMergeBase
132			syncCheckpointPolicyForPrePush(ctx, repo, ps)
133			if !checkpointPolicyAllowsGitHook(ctx, repo) {
134				// Policy failures should skip checkpoint pushes, not abort the user's push.
135				return nil
136			}
137			if err := prepareOversizedV1ForPush(
138				ctx, repo, ps.pushTarget(), OversizedCheckpointMetadataThreshold,
139			); err != nil {
140				logging.Warn(ctx, "checkpoint metadata cleanup failed; aborting push",
141					slog.String("error", err.Error()),
142				)
143				fmt.Fprintf(os.Stderr, "[entire] Checkpoint metadata cleanup failed: %v\n", err)
144				return err
145			}
146		}
147	
148		// OPF pre-push rewrite: if OPF is configured, resolve the user's
149		// decision (env > settings > prompt > non-TTY auto-run), then
150		// re-redact unpushed v1 commits with OPF (producing the OPF-applied,
301	func newHooksGitPrePushCmd() *cobra.Command {
302		return &cobra.Command{
303			Use:   "pre-push <remote>",
304			Short: "Handle pre-push git hook",
305			Args:  cobra.ExactArgs(1),
306			// SilenceUsage/Errors so non-zero exits from privacy-critical
307			// failures (OPF rewrite errors) print only the error message,
308			// not cobra's usage banner. The error message itself already
309			// includes user guidance (see ErrV1Diverged / ErrBootstrapTooLarge /
310			// ErrV1RefMoved in strategy/manual_commit_opf_rewrite.go).
311			SilenceUsage:  true,
312			SilenceErrors: false,
313			RunE: func(cmd *cobra.Command, args []string) error {
314				if gitHooksDisabled {
315					return nil
316				}
317	
318				remote := args[0]
319	
320				g := newGitHookContext(cmd.Context(), "pre-push")
321				defer g.span.End()
322				g.logInvoked(slog.String("remote", remote))
323	
324				hookErr := g.strategy.PrePushFromGitHook(g.ctx, remote)
325				g.logCompleted(hookErr)
326	
327				// Propagate the error so the hook script exits non-zero and
328				// git push aborts the entire batch. PrePush itself only
329				// returns errors for privacy-critical failures (OPF rewrite —
330				// e.g., V1DivergedError, BootstrapTooLargeError,
331				// V1RefMovedError, OPFRuntimeFailedError,
332				// OPFNoCategoriesError); transient
333				// checkpoint-push failures are logged and swallowed before
334				// reaching this point. See strategy/manual_commit_push.go
335				// for the contract. We wrap with a short "pre-push:" prefix
336				// so the user sees the source of the abort without losing
337				// the underlying type (errors.As still finds the sentinels).
338				if hookErr == nil {
339					return nil
340				}
341				return fmt.Errorf("pre-push: %w", hookErr)
342			},
343		}

