450	func computeMergeBaseWithGit(
451		ctx context.Context,
452		repoPath string,
453		local, remote plumbing.Hash,
454	) (plumbing.Hash, error) {
455		cmd := exec.CommandContext(ctx, "git", "merge-base", "--all", local.String(), remote.String())
456		cmd.Dir = repoPath
457		output, err := cmd.Output()
458		if err != nil {
459			var exitErr *exec.ExitError
460			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
461				return plumbing.ZeroHash, nil
462			}
463			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
464		}
465		bases := strings.Fields(string(output))
466		if len(bases) != 1 {
467			return plumbing.ZeroHash, nil
468		}
469		return plumbing.NewHash(bases[0]), nil
470	}
