472	func boundaryAtOrAfterMergeBase(
473		ctx context.Context,
474		repoPath string,
475		mergeBase, boundary plumbing.Hash,
476	) (bool, error) {
477		if mergeBase.Equal(boundary) {
478			return true, nil
479		}
480		cmd := exec.CommandContext(ctx, "git", "merge-base", "--is-ancestor", mergeBase.String(), boundary.String())
481		cmd.Dir = repoPath
482		if err := cmd.Run(); err != nil {
483			var exitErr *exec.ExitError
484			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
485				return false, nil
486			}
487			return false, fmt.Errorf("compare repaired boundary with original merge-base: %w", err)
488		}
489		return true, nil
490	}

