   713	func (r *metadataRewriter) rewriteTree(hash plumbing.Hash, prefix string) (plumbing.Hash, error) {
   714		if done, ok := r.trees[hash]; ok {
   715			return done, nil
   716		}
   717		tree, err := r.repo.TreeObject(hash)
   718		if err != nil {
   719			return plumbing.ZeroHash, fmt.Errorf("load tree %s: %w", hash, err)
   720		}
   721		entries := make([]object.TreeEntry, 0, len(tree.Entries))
   722		changed := false
   723		for _, e := range tree.Entries {
   724			entryPath := e.Name
   725			if prefix != "" {
   726				entryPath = prefix + "/" + e.Name
   727			}
   728			newEntry := e
   729			switch e.Mode {
   730			case filemode.Dir:
   731				sub, subErr := r.rewriteTree(e.Hash, entryPath)
   732				if subErr != nil {
   733					return plumbing.ZeroHash, subErr
   734				}
   735				newEntry.Hash = sub
   736			case filemode.Regular, filemode.Executable, filemode.Deprecated:
   737				if e.Name == paths.MetadataFileName {
   738					blob, blobErr := r.rewriteBlob(e.Hash, entryPath)
   739					if blobErr != nil {
   740						return plumbing.ZeroHash, blobErr
   741					}
   742					newEntry.Hash = blob
   743				}
   744			case filemode.Empty, filemode.Symlink, filemode.Submodule:
   745				// kept verbatim
   746			}
   747			if !newEntry.Hash.Equal(e.Hash) {
   748				changed = true
   749			}
   750			entries = append(entries, newEntry)
   751		}
   752		if !changed {
   753			r.trees[hash] = hash
   754			return hash, nil
   755		}
   756		newTree := &object.Tree{Entries: entries}
   757		obj := r.repo.Storer.NewEncodedObject()
   758		if err := newTree.Encode(obj); err != nil {
   759			return plumbing.ZeroHash, fmt.Errorf("encode tree %s: %w", prefix, err)
   760		}
   761		newHash, err := r.repo.Storer.SetEncodedObject(obj)
   762		if err != nil {
   763			return plumbing.ZeroHash, fmt.Errorf("store tree %s: %w", prefix, err)
   764		}
   765		r.trees[hash] = newHash
   766		return newHash, nil
   767	}
