   777		if err != nil {
   778			return plumbing.ZeroHash, fmt.Errorf("load blob %s at %s: %w", hash, blobPath, err)
   779		}
   780		if blob.Size <= r.threshold {
   781			r.blobs[hash] = hash
   782			return hash, nil
   783		}
   784		data, err := readBlob(r.repo, hash)
   785		if err != nil {
   786			return plumbing.ZeroHash, fmt.Errorf("read blob %s at %s: %w", hash, blobPath, err)
   787		}
   788		stripped, changed, err := stripPromptAttributions(data)
