   791			// other than the field it knows how to remove: leave it and say so
   792			// rather than guess at what to delete.
   793			r.stillOversized = append(r.stillOversized, OversizedMetadataBlob{Path: blobPath, Size: blob.Size, Hash: hash})
   794			r.blobs[hash] = hash
   795			return hash, nil //nolint:nilerr // deliberate: an unparseable blob is kept verbatim and reported via stillOversized
   796		}
