   798		if err != nil {
   799			return plumbing.ZeroHash, fmt.Errorf("write shrunk blob for %s: %w", blobPath, err)
   800		}
   801		r.blobsShrunk++
   802		if int64(len(stripped)) > r.threshold {
   803			r.stillOversized = append(r.stillOversized, OversizedMetadataBlob{Path: blobPath, Size: int64(len(stripped)), Hash: newHash})
   804		}
   805		r.blobs[hash] = newHash
   806		return newHash, nil
   807	}
