   105	// reconcileOversizedV1ForPush rewrites local oversized history. An existing
   106	// remote must prove where its shared checkpoint content ends before replay.
   107	func reconcileOversizedV1ForPush(
   108		ctx context.Context,
   109		repo *git.Repository,
   110		observedLocalTip, remoteTip plumbing.Hash,
   111		threshold int64,
   112	) (plumbing.Hash, bool, error) {
   113		if observedLocalTip.IsZero() {
   114			return observedLocalTip, false, nil
   115		}
   116		repoPath, err := getRepoPath(repo)
   117		if err != nil {
   118			return plumbing.ZeroHash, false, fmt.Errorf("get repository path: %w", err)
   119		}
   120	
   121		mergeBase := plumbing.ZeroHash
   122		if !remoteTip.IsZero() {
   123			mergeBase, err = computeMergeBaseWithGit(ctx, repoPath, observedLocalTip, remoteTip)
   124			if err != nil {
   125				return plumbing.ZeroHash, false, fmt.Errorf("compute original merge-base: %w", err)
   126			}
   127			remoteHasOversizedHistory, scanErr := hasOversizedMetadataIntroducedSince(
   128				ctx, repo, remoteTip, plumbing.ZeroHash, threshold,
   129			)
   130			if scanErr != nil {
   131				return plumbing.ZeroHash, false, fmt.Errorf("scan remote checkpoint metadata: %w", scanErr)
   132			}
   133			if remoteHasOversizedHistory {
   134				return observedLocalTip, false, nil
   135			}
   136		}
   137		hasOversizedLocalHistory, err := hasOversizedMetadataIntroducedSince(
   138			ctx, repo, observedLocalTip, mergeBase, threshold,
   139		)
   140		if err != nil {
   141			return plumbing.ZeroHash, false, err
   142		}
   143		if !hasOversizedLocalHistory {
   144			return observedLocalTip, false, nil
   145		}
   146	
   147		shallow, err := loadShallowHashes(ctx, repoPath)
   148		if err != nil {
   149			return plumbing.ZeroHash, false, fmt.Errorf("load shallow boundaries: %w", err)
   150		}
   151		rewriter := newMetadataRewriter(ctx, repo, threshold)
   152		rewriter.shallow = shallow
   153		rewrittenTip, err := rewriter.rewriteHistory(observedLocalTip)
   154		if err != nil {
   155			return plumbing.ZeroHash, false, fmt.Errorf("rewrite oversized local metadata: %w", err)
   156		}
   157		if rewriter.commitsRewritten == 0 {
   158			return observedLocalTip, false, nil
   159		}
   160		if remoteTip.IsZero() {
   161			if err := atomicSetV1Ref(ctx, repo, observedLocalTip, rewrittenTip); err != nil {
   162				return plumbing.ZeroHash, false, err
   163			}
   164			return rewrittenTip, true, nil
   165		}
   166	
   167		rewrittenBoundary, originalBoundary, found, err := findSharedRewrittenTree(
   168			ctx, repo, repoPath, rewrittenTip, remoteTip, rewriter.commits,
   169		)
   170		if err != nil {
   171			return plumbing.ZeroHash, false, err
   172		}
   173		if !found {
   174			return observedLocalTip, false, nil
   175		}
   176	
   177		if !mergeBase.IsZero() {
   178			safe, err := boundaryAtOrAfterMergeBase(ctx, repoPath, mergeBase, originalBoundary)
   179			if err != nil {
   180				return plumbing.ZeroHash, false, err
   181			}
   182			if !safe {
   183				return observedLocalTip, false, nil
   184			}
   185		}
   186	
   187		localOnly, err := collectFirstParentCommitsSince(ctx, repo, repoPath, rewrittenTip, rewrittenBoundary)
   188		if err != nil {
   189			return plumbing.ZeroHash, false, fmt.Errorf("collect local checkpoints after repaired boundary: %w", err)
   190		}
   191	
   192		newTip := remoteTip
   193		if len(localOnly) > 0 {
   194			shallow, shallowErr := loadShallowHashes(ctx, repoPath)
   195			if shallowErr != nil {
   196				return plumbing.ZeroHash, false, fmt.Errorf("load shallow boundaries: %w", shallowErr)
   197			}
   198			newTip, err = cherryPickOnto(ctx, repo, remoteTip, localOnly, shallow)
   199			if err != nil {
   200				return plumbing.ZeroHash, false, fmt.Errorf("replay local checkpoints onto repaired remote: %w", err)
   201			}
   202		}
   203	
   204		if err := atomicSetV1Ref(ctx, repo, observedLocalTip, newTip); err != nil {
   205			return plumbing.ZeroHash, false, err
   350			}
   351			if errors.Is(readErr, io.EOF) {
   352				break
   353			}
   354		}
   355		if err := objectsCmd.Wait(); err != nil {
   356			waited = true
   357			return false, fmt.Errorf("list local checkpoint metadata objects: %s: %w", strings.TrimSpace(stderr.String()), err)
   358		}
   359		waited = true
   360		return found, nil
   361	}
   362	
   363	func findSharedRewrittenTree(
   364		ctx context.Context,
   365		repo *git.Repository,
   366		repoPath string,
   367		rewrittenLocalTip, remoteTip plumbing.Hash,
   368		originalToRewritten map[plumbing.Hash]plumbing.Hash,
   369	) (rewritten, original plumbing.Hash, found bool, err error) {
   370		remoteTrees := make(map[plumbing.Hash]struct{})
   371		remoteHistory, err := reachableHistory(ctx, repo, repoPath, remoteTip)
   372		if err != nil {
   373			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log remote checkpoint history: %w", err)
   374		}
   375		for _, commit := range remoteHistory {
   376			if err := ctx.Err(); err != nil {
   377				return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("scan remote checkpoint trees: %w", err)
   378			}
   379			remoteTrees[commit.TreeHash] = struct{}{}
   380		}
   381	
   382		rewrittenToOriginal := make(map[plumbing.Hash]plumbing.Hash, len(originalToRewritten))
   383		for oldHash, newHash := range originalToRewritten {
   384			rewrittenToOriginal[newHash] = oldHash
   385		}
   386		localHistory, err := firstParentHistory(ctx, repo, repoPath, rewrittenLocalTip)
   387		if err != nil {
   388			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log rewritten local checkpoint history: %w", err)
   389		}
   390		for _, commit := range localHistory {
   391			if err := ctx.Err(); err != nil {
   392				return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("scan rewritten local checkpoint trees: %w", err)
   393			}
   394			if _, exists := remoteTrees[commit.TreeHash]; !exists {
   395				continue
   396			}
   397			oldHash, exists := rewrittenToOriginal[commit.Hash]
   398			if !exists {
   399				return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("rewritten commit %s has no original", commit.Hash)
   400			}
   401			return commit.Hash, oldHash, true, nil
   402		}
   403		return plumbing.ZeroHash, plumbing.ZeroHash, false, nil
   404	}
   405	
   406	func reachableHistory(
   407		ctx context.Context,
   408		repo *git.Repository,
   409		repoPath string,
   410		tip plumbing.Hash,
   411	) ([]*object.Commit, error) {
   412		return historyFromRevList(ctx, repo, repoPath, tip.String())
   413	}
   414	
   415	func firstParentHistory(
   416		ctx context.Context,
   417		repo *git.Repository,
   418		repoPath string,
   419		tip plumbing.Hash,
   420	) ([]*object.Commit, error) {
   421		return historyFromRevList(ctx, repo, repoPath, "--first-parent", tip.String())
   422	}
   423	
   424	func historyFromRevList(
   425		ctx context.Context,
   426		repo *git.Repository,
   427		repoPath string,
   428		args ...string,
   429	) ([]*object.Commit, error) {
   430		cmd := exec.CommandContext(ctx, "git", append([]string{"rev-list"}, args...)...)
   431		cmd.Dir = repoPath
   432		output, err := cmd.Output()
   433		if err != nil {
   434			return nil, fmt.Errorf("git rev-list failed: %w", err)
   435		}
   436		hashes := strings.Fields(string(output))
   437		commits := make([]*object.Commit, 0, len(hashes))
   438		for _, value := range hashes {
   439			commit, err := repo.CommitObject(plumbing.NewHash(value))
   440			if err != nil {
   441				return nil, fmt.Errorf("load first-parent commit %s: %w", value, err)
   442			}
   443			commits = append(commits, commit)
   444		}
   445		return commits, nil
   446	}
   447	
   448	func collectFirstParentCommitsSince(
   449		ctx context.Context,
   450		repo *git.Repository,
   451		repoPath string,
   452		tip, boundary plumbing.Hash,
   453	) ([]*object.Commit, error) {
   454		cmd := exec.CommandContext(
   455			ctx, "git", "rev-list", "--first-parent", "--reverse", boundary.String()+".."+tip.String(),
   456		)
   457		cmd.Dir = repoPath
   458		output, err := cmd.Output()
   459		if err != nil {
   460			return nil, fmt.Errorf("git rev-list failed: %w", err)
   461		}
   462		hashes := strings.Fields(string(output))
   463		if len(hashes) > MaxCommitTraversalDepth {
   464			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
   465		}
   466		commits := make([]*object.Commit, 0, len(hashes))
   467		for _, value := range hashes {
   468			commit, err := repo.CommitObject(plumbing.NewHash(value))
   469			if err != nil {
   470				return nil, fmt.Errorf("load replay commit %s: %w", value, err)
   471			}
   472			commits = append(commits, commit)
   473		}
   474		return commits, nil
   475	}
   476	
   477	func computeMergeBaseWithGit(
